/* Reusable laboratory apparatus: visible tube lumens, connectors, instrument
   panels, hollow tapered vessels and measurable maize kernels. */
(()=>{'use strict';const TAU=Math.PI*2,add=(a,b)=>a.map((x,i)=>x+b[i]),sub=(a,b)=>a.map((x,i)=>x-b[i]),mul=(a,s)=>a.map(x=>x*s),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],norm=a=>mul(a,1/(Math.hypot(...a)||1));
function ring(w,x,y,z,r,c='#b8c5ba',width=1.5){w.line(Array.from({length:41},(_,i)=>[x+Math.cos(i/40*TAU)*r,y,z+Math.sin(i/40*TAU)*r]),c,width)}
function bevel(w,x,y,z,width,height,depth,color='#d3d7cc'){const b=.12*Math.min(width,depth),pts=[[-width/2+b,-depth/2],[width/2-b,-depth/2],[width/2,-depth/2+b],[width/2,depth/2-b],[width/2-b,depth/2],[-width/2+b,depth/2],[-width/2,depth/2-b],[-width/2,-depth/2+b]],low=pts.map(p=>[x+p[0],y,z+p[1]]),up=pts.map(p=>[x+p[0]*.98,y+height,z+p[1]*.98]);for(let i=0;i<8;i++)w.poly([low[i],low[(i+1)%8],up[(i+1)%8],up[i]],color);w.poly(up,color);}
function aperture(w,p,tangent,r=.07){const d=norm(tangent),u=norm(cross(d,Math.abs(d[1])>.9?[1,0,0]:[0,1,0])),v=cross(d,u);for(let i=0;i<14;i++){const a=i/14*TAU,b=(i+1)/14*TAU,f=(t,s)=>add(p,add(mul(u,Math.cos(t)*s),mul(v,Math.sin(t)*s)));w.poly([f(a,r),f(b,r),f(b,r*.58),f(a,r*.58)],'#d7e2db');} }
function tube(w,points,{medium='liquid',active=false,count=10}={}){w.line(points,'#91aaa4',7,{alpha:.68});w.line(points,'#e3ede6',4.8,{alpha:.9});w.line(points,medium==='air'?'#d3dfcf':'#a7cad0',2.6,{alpha:.7});aperture(w,points[0],sub(points[1],points[0]));aperture(w,points.at(-1),sub(points.at(-1),points.at(-2)));if(active){if(medium==='liquid'){for(let i=0;i<count;i++){const t=(w.time*.13+i/count)%1,a=w.pathPoint(points,t),b=w.pathPoint(points,Math.min(.999,t+.037));w.line([a,b],'#529eaf',2.7,{alpha:.82});w.dot(a,.022,'#9bd1d9',{alpha:.8})}}else for(let i=0;i<count;i++){const p=w.pathPoint(points,(w.time*.18+i/count)%1);w.dot(p,.026,'#f2f6e7',{alpha:.94});aperture(w,p,sub(points.at(-1),points[0]),.032)}}}
function pump(w,x,y,z,{active=true,scale=1}={}){bevel(w,x,y,z,1.55*scale,.55*scale,1.02*scale,'#c6cebd');bevel(w,x,y+.48*scale,z,1.48*scale,.15*scale,.98*scale,'#748a72');for(let i=0;i<7;i++)w.line([[x-.47*scale+i*.15*scale,y+.28*scale,z-.505*scale],[x-.47*scale+i*.15*scale,y+.43*scale,z-.505*scale]],'#687c68',1.7);for(let side of [-1,1])for(let end of [-1,1])w.cylinder(x+side*.54*scale,y-.06*scale,z+end*.31*scale,.09*scale,.08*scale,'#6f7c69',{n:10});w.box(x+.44*scale,y+.64*scale,z-.08*scale,.22*scale,.05*scale,.25*scale,'#536d58');w.dot([x-.44*scale,y+.65*scale,z-.1*scale],.046*scale,active?'#8dbd6f':'#9ca393',{glow:active});w.cylinder(x,y+.63*scale,z+.28*scale,.16*scale,.06*scale,'#a3b39a',{n:18});w.line([[x,y+.7*scale,z+.28*scale],[x+.1*scale,y+.7*scale,z+.3*scale]],'#5a745b',1.4);w.line([[x,y+.18*scale,z+.52*scale],[x,y+.18*scale,z+.78*scale]],'#ab956a',5);w.dot([x-.68*scale,y+.56*scale,z-.35*scale],.025*scale,'#7a8b73');w.dot([x+.68*scale,y+.56*scale,z-.35*scale],.025*scale,'#7a8b73');}
const digits={'0':'abcedf','1':'bc','2':'abged','3':'abgcd','4':'fgbc','5':'afgcd','6':'afgecd','7':'abc','8':'abcdefg','9':'abfgcd','-':'g'},segments={a:[[0,1],[1,1]],b:[[1,1],[1,.5]],c:[[1,.5],[1,0]],d:[[0,0],[1,0]],e:[[0,0],[0,.5]],f:[[0,.5],[0,1]],g:[[0,.5],[1,.5]]};
function display(w,x,y,z,text,scale=1){let at=x;for(const ch of text){if(ch==='.'){w.line([[at,y,z],[at+.008*scale,y,z]],'#b3dfab',2*scale,{layer:4});at+=.055*scale;continue}for(const s of digits[ch]||[]){const a=segments[s];w.line(a.map(p=>[at+p[0]*.1*scale,y+p[1]*.22*scale,z]),'#b1dfaa',1.7*scale,{layer:4})}at+=.15*scale}}
function balance(w,x,y,z,{value='0.00',unit='g',large=false,stable=true}={}){const a=large?1.3:1;bevel(w,x,y,z,2.8*a,.38*a,2.2*a,'#c8cec3');w.box(x,y+.1*a,z-1.14*a,1.72*a,.29*a,.045*a,'#3f5e50');if(Math.cos(w.current?.yaw??0)>.1)display(w,x-.69*a,y+.135*a,z-1.181*a,value,.98*a);w.label([x+.53*a,y+.24*a,z-1.19*a],unit,{size:9,color:'#b6d7a8'});w.cylinder(x,y+.41*a,z+.15*a,.94*a,.07*a,'#8d9b93',{n:40});w.cylinder(x,y+.48*a,z+.15*a,1.03*a,.07*a,'#d3dad5',{n:40});for(let r of [.3,.53,.76,.99])ring(w,x,y+.557*a,z+.15*a,r*a,'#bac6bd',.55);for(let side of [-1,1]){w.cylinder(x+side*1.08*a,y-.06*a,z-.78*a,.08*a,.09*a,'#7d8b78',{n:10});w.box(x+side*1.05*a,y+.39*a,z-.71*a,.26*a,.035*a,.22*a,side<0?'#92ab87':'#b1bca7');}w.dot([x+.98*a,y+.42*a,z-.34*a],.026*a,stable?'#8db47d':'#cbb474');return {panY:y+.56*a,panZ:z+.15*a};}
function pot(w,x,y,z,type='soil',{r=1.25,height=1.8,fill=true,cutaway=true}={}){const bot=r*.77,wall=.085,top=y+height,n=36,medium=type==='soil'?'#a68b62':type==='sand'?'#d9ca9f':'#9ac4c8';w.cylinder(x,y,z,bot,.1,'#a0b195',{n:32});for(let i=0;i<n;i++){const a=i/n*TAU,b=(i+1)/n*TAU;if(cutaway&&Math.sin((a+b)/2)<-.4)continue;const p=(t,rr,h)=>[x+Math.cos(t)*rr,h,z+Math.sin(t)*rr];w.poly([p(a,bot,y),p(b,bot,y),p(b,r,top),p(a,r,top)],'#c1cdb2',{line:'#dce3d1'});w.poly([p(a,bot-wall,y+.1),p(a,r-wall,top),p(b,r-wall,top),p(b,bot-wall,y+.1)],'#d6deca');w.poly([p(a,r,top),p(b,r,top),p(b,r-wall,top),p(a,r-wall,top)],'#e2e9d7');}ring(w,x,top+.02,z,r+.02,'#e0e8d5',3);ring(w,x,y+.13,z,bot+.015,'#8fa486',2);if(fill){w.cylinder(x,y+.12,z,bot-wall,height-.25,medium,{n:32,alpha:type==='hydro'?.36:.43});if(type!=='hydro')for(let i=0;i<75;i++){const t=i*2.399,rr=(r-wall-.1)*Math.sqrt((i+.5)/75);w.dot([x+Math.cos(t)*rr,top-.12,z+Math.sin(t)*rr],.018+(i%3)*.01,type==='soil'?['#a18559','#b99a6a','#8c724d'][i%3]:['#e9dcb5','#c8b68b','#dacb9d'][i%3]);}}if(type==='hydro'){for(let i=0;i<n;i++){const a=i/n*TAU,b=(i+1)/n*TAU,p=(t,rr)=>[x+Math.cos(t)*rr,top+.04,z+Math.sin(t)*rr];w.poly([p(a,.19),p(a,r+.02),p(b,r+.02),p(b,.19)],'#8ca181')}w.cylinder(x,top+.06,z,.18,.08,'#d8e0cb',{n:18});}return top-.08;}
function kernel(w,x,y,z,{size=.1,color='#dcad46'}={}){const a=size*.68,b=size*.44,h=size*.8,p=[[x-a,y,z-b],[x+a,y,z-b],[x+a*.82,y+h,z-b*.6],[x-a*.82,y+h,z-b*.6]],q=p.map(v=>[v[0],v[1],2*z-v[2]]);w.poly(p,color);w.poly([p[1],q[1],q[2],p[2]],'#c8983d');w.poly([p[2],q[2],[x,y+h*.87,z],q[3],p[3]],'#edd081');}
window.CultureEquipment={tube,pump,balance,pot,kernel,bevel,ring};
})();



